r"""规范建议 4 的落地器：为「作者字段无出处」的 source 页补写来源标注。

背景
----
`qc_author_gate.py` 扫出 19 个 source 页：`authors:` **非空**，但**其 raw 回链中
检索不到任何作者/单位信息栏**。这些作者值是**真实且正确**的（如
`Yi Shi, Shu-Lei Chou, Hua-Kun Liu…` 确为该文作者），但**在本库内无法回溯**。

处置选择（为什么不直接留白）
--------------------------
CLAUDE.md 规定「raw 作者栏未落库时**强制留白，不得补写**」。
但**本次的 19 页不是「补写」而是「已写」**——直接抹掉会**丢失正确信息**，
比标注更糟。⇒ 采用**等效的诚实做法**：

  在 frontmatter 加 `authors_source` 字段，写明该值的**实际出处**与**不可回溯性**：

      authors_source: "raw 剪藏未含作者信息栏（publisher HTML 剥空）；\
      本字段值来自 Crossref/OpenAlex 反查，库内不可回溯，引用前须自行核验"

这样既满足「不得让读者误以为有出处」的规范目的，又保留正确信息。

用法
----
  python tools/qc_author_gate_apply.py            # 干跑
  python tools/qc_author_gate_apply.py --apply    # 就地写入
  python tools/qc_author_gate_apply.py --selftest  # 校验器自检
"""
import sys
import os
import re

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
os.chdir(ROOT)
sys.path.insert(0, "tools")
from kb_lib import read_text, split_frontmatter, join_frontmatter  # noqa: E402
from kb_lib import console_encoding
console_encoding()
from qc_author_gate import scan  # noqa: E402

MARKER = ("raw 剪藏未含作者信息栏（publisher HTML 剥空）；本字段值来自 "
          "Crossref/OpenAlex 反查，**库内不可回溯**，引用前须自行核验")


def insert_marker(fm_text):
    """纯函数：把 `authors_source` 行插进 frontmatter 文本。返回 (新文本, 是否改动)。

    插入位置：`authors:` 块（含其列表项）之后；无 `authors:` 则紧随 `type:` 之后；
    都没有则追加到末尾。
    """
    if re.search(r"^authors_source\s*:", fm_text, re.M):
        return fm_text, False                  # 幂等：已有则不重复写
    lines = fm_text.split("\n")
    insert_at = None
    for i, ln in enumerate(lines):
        if re.match(r"^authors\s*:", ln):
            j = i + 1
            while j < len(lines) and re.match(r"^\s+-\s", lines[j]):
                j += 1
            insert_at = j
            break
    if insert_at is None:
        for i, ln in enumerate(lines):
            if re.match(r"^type\s*:", ln):
                insert_at = i + 1
                break
    if insert_at is None:
        insert_at = len(lines)
    # ⚠️ 必须整体加双引号——内容含 `；` 与 `**`，且本库教训是「长文本字段不加引号
    #    会让整个 frontmatter 解析失败」（曾 49 页中招）
    lines.insert(insert_at, f'authors_source: "{MARKER}"')
    return "\n".join(lines), True


def selftest():
    """校验器自检：已知答案反算（正例 + 反例）。

    本脚本是**写盘脚本**，铁律是「写前用与被校验系统同一个解析器复核」。
    夹具必须钉住：① 插入位置正确；② 幂等；③ **修后 frontmatter 仍可被
    `kb_lib.split_frontmatter` 读出**（本库最高代价失效形态）。
    """
    import yaml as _yaml
    ok = True

    # 正例：插在 authors 块（含列表项）之后，而不是插进列表中间
    fm = ("created: 2026-01-01\nauthors:\n  - \"A B\"\n  - \"C D\"\ntype: source\n"
          'summary: "x"')
    new, changed = insert_marker(fm)
    lines = new.split("\n")
    ai = lines.index('  - "C D"')
    good = changed and lines[ai + 1].startswith("authors_source:")
    print(f"  [{'ok' if good else 'FAIL'}] 正例 插在 authors 列表项之后")
    ok = ok and good

    # 正例：无 authors 时紧随 type 之后
    fm2 = 'created: 2026-01-01\ntype: source\nsummary: "x"'
    new2, changed2 = insert_marker(fm2)
    lines2 = new2.split("\n")
    good = changed2 and lines2[lines2.index("type: source") + 1].startswith("authors_source:")
    print(f"  [{'ok' if good else 'FAIL'}] 正例 无 authors 时紧随 type")
    ok = ok and good

    # 正例：幂等——已有 authors_source 时不得再插
    fm3 = 'created: 2026-01-01\nauthors_source: "已存在"\ntype: source'
    new3, changed3 = insert_marker(fm3)
    good = (not changed3) and new3 == fm3
    print(f"  [{'ok' if good else 'FAIL'}] 正例 幂等（已有则不重复写）")
    ok = ok and good

    # 🔴 关键正例：修后必须能被**同一解析器**读出（本库 124 页事故形态）
    for label, fmx in (("有 authors", fm), ("无 authors", fm2)):
        newx, _ = insert_marker(fmx)
        full = join_frontmatter(newx, "# 标题\n正文\n")
        got_fm, got_body = split_frontmatter(full)
        parsed = None
        if got_fm:
            try:
                parsed = _yaml.safe_load(got_fm)
            except Exception:
                parsed = None
        good = (got_fm != "" and isinstance(parsed, dict)
                and "authors_source" in parsed
                and got_body.lstrip().startswith("# 标题"))
        print(f"  [{'ok' if good else 'FAIL'}] 🔴 修后 frontmatter 可解析（{label}）")
        ok = ok and good

    # 正例：MARKER 会被整体加双引号（内含 `；` 与 `**`，不加引号必坏）
    newx, _ = insert_marker(fm)
    line = [l for l in newx.split("\n") if l.startswith("authors_source:")][0]
    good = line.startswith('authors_source: "') and line.endswith('"')
    print(f"  [{'ok' if good else 'FAIL'}] 正例 marker 整体加双引号")
    ok = ok and good

    print("=== selftest", "PASS ===" if ok else "FAIL ===")
    return 0 if ok else 1


def apply_marker(page):
    f = f"wiki/sources/{page}.md"
    t = read_text(f)
    a, b = split_frontmatter(t)
    if not a:
        print(f"  SKIP（frontmatter 解析失败）: {page}")
        return False
    a2, changed = insert_marker(a)
    if not changed:
        return False                      # 幂等：已有则不重复写
    new = join_frontmatter(a2, b)
    # 写前断言：用与 kb_lib 相同的解析器复核（不另写正则）
    if not split_frontmatter(new)[0]:
        print(f"  ABORT（会破坏 frontmatter）: {page}")
        return False
    with open(f, "w", encoding="utf-8", newline="") as fh:
        fh.write(new)
    return True


def main():
    if "--help" in sys.argv or "-h" in sys.argv:
        print(__doc__ or "用法: python tools/qc_author_gate_apply.py [--apply] [--selftest]")
        return 0
    if "--selftest" in sys.argv:
        return selftest()
    apply = "--apply" in sys.argv
    rows = [r for r in scan() if r["kind"] == "作者字段无出处"]
    print(f"待标注：{len(rows)} 页\n")
    for r in rows:
        print(f"  {r['page'][:60]}")
    if not apply:
        print("\n加 --apply 就地写入 authors_source 标注")
        return 0
    n = 0
    print()
    for r in rows:
        if apply_marker(r["page"]):
            n += 1
            print(f"  已标注: {r['page'][:60]}")
    print(f"\n共写入 {n} 页")
    return 0


if __name__ == "__main__":
    sys.exit(main())
